css:
:scope{display:block;width:100%}.pw{--bg:#0F0E0C;--tx:#EDE6D8;--lb:#C2B8A6;--hl:#3A3531;--ol:#C2B8A6;background:var(--bg);color:var(--tx);font-family:var(--os-font-body);font-weight:400}.pw[data-ground="bone"]{--bg:#EDE6D8;--tx:#0F0E0C;--lb:#3A3531;--hl:#3A3531;--ol:#0F0E0C}.pw[data-ground="umber"]{--bg:#3A3531;--hl:#C2B8A6}.pw[data-ground="oxblood"]{--bg:#4A1C18;--hl:#C2B8A6}.pw[data-ground="clay"]{--bg:#8E4A30;--lb:#EDE6D8;--hl:#EDE6D8;--ol:#EDE6D8}.pw[data-ground="olive"]{--bg:#3C402F;--hl:#C2B8A6}
.pw__in{box-sizing:content-box;max-width:1200px;margin:0 auto;padding:96px 32px;display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:48px}
.pw__blk{border-top:1px solid var(--hl);padding-top:28px}
.pw__kicker{margin:0;font-family:var(--os-font-label);font-weight:400;font-size:12px;letter-spacing:.3em;text-transform:uppercase;color:var(--lb)}
.pw__hl{margin:16px 0 0;font-family:var(--os-font-heading);font-weight:500;font-size:32px;line-height:1.2}
.pw__bd{margin:12px 0 0;font-size:19px;line-height:1.5;color:var(--lb)}
.pw__btns{display:flex;flex-wrap:wrap;gap:14px;margin-top:24px}
.pw__btn{display:inline-block;font-family:var(--os-font-label);font-weight:400;font-size:12px;letter-spacing:.22em;text-transform:uppercase;text-decoration:none;line-height:normal;color:var(--tx);border:1px solid var(--ol);padding:15px 22px}
.pw__btn:focus-visible{outline:2px solid var(--tx);outline-offset:3px}
@media (max-width:767px){.pw__in{padding:56px 20px;grid-template-columns:1fr;gap:40px}.pw__kicker{font-size:11px}.pw__hl{font-size:27px}.pw__btns{flex-direction:column}.pw__btn{text-align:center}}
